namespace LeoLauncher;
sealed class ComputerStatusForm:BarcaWindow
{
    readonly ComputerMonitor monitor;readonly Preferences prefs;readonly Label cpu=new(),memory=new(),network=new(),disk=new(),stamp=new();readonly ListView processes=new(){View=View.Details,FullRowSelect=true,BorderStyle=BorderStyle.None,HideSelection=false,OwnerDraw=true};readonly ModuleThemeBinding theme;readonly CheckBox alerts=new();bool sortCpu=true;
    static string Bytes(double? value)=>value==null?"—":value>=1073741824?$"{value/1073741824:0.0} GB":value>=1048576?$"{value/1048576:0.0} MB":$"{value/1024:0.0} KB";
    public ComputerStatusForm(ComputerMonitor monitor,Preferences prefs,Action<Action<Preferences>> save,Func<string,Task> run)
    {
        this.monitor=monitor;this.prefs=prefs;Text="Leo · 电脑状态";ClientSize=new(720,600);Controls.Add(BarcaUi.Chrome(this,"电脑状态","轻量资源速览 · 需要深入处理时打开任务管理器"));
        void Metric(string name,Label value,int x,int y){var card=new RoundedSurface{Bounds=new(x,y,326,78),BackColor=BarcaUi.Surface};card.Controls.Add(new Label{Text=name,Bounds=new(14,9,296,20),ForeColor=BarcaUi.Muted});value.Bounds=new(14,34,298,30);value.Font=BarcaUi.Font(13,true);value.ForeColor=BarcaUi.Text;value.Text="正在采样…";card.Controls.Add(value);Controls.Add(card);}
        Metric("CPU · 多核总占用",cpu,24,104);Metric("物理内存",memory,370,104);Metric("网卡合计估算 · 含虚拟网卡",network,24,194);Metric("系统盘剩余容量",disk,370,194);
        processes.Bounds=new(24,285,672,190);processes.BackColor=BarcaUi.Surface;processes.ForeColor=BarcaUi.Text;processes.Columns.Add("进程",295);processes.Columns.Add("PID",80);processes.Columns.Add("CPU",100);processes.Columns.Add("内存",197);processes.ColumnClick+=(_,e)=>{if(e.Column is 2 or 3){sortCpu=e.Column==2;Render();}};processes.DrawColumnHeader+=(_,e)=>{using var brush=new SolidBrush(BarcaUi.Raised);e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,e.Header?.Text??"",Font,e.Bounds,BarcaUi.Muted,TextFormatFlags.VerticalCenter);};processes.DrawItem+=(_,_)=>{};processes.DrawSubItem+=(_,e)=>{using var brush=new SolidBrush(e.Item!.Selected?BarcaUi.Raised:BarcaUi.Surface);e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,e.SubItem?.Text??"",Font,e.Bounds,BarcaUi.Text,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);};Controls.Add(processes);
        stamp.Bounds=new(24,481,672,36);stamp.ForeColor=BarcaUi.Muted;stamp.Font=BarcaUi.Font(8.5f);Controls.Add(stamp);
        alerts.Text="后台提醒持续高占用（默认关闭，持续30秒才提示）";alerts.Checked=prefs.SystemMonitorAlerts;alerts.Bounds=new(24,520,670,26);alerts.ForeColor=BarcaUi.Text;bool changing=false;alerts.CheckedChanged+=(_,_)=>{if(changing)return;try{save(p=>p.SystemMonitorAlerts=alerts.Checked);}catch(Exception e){changing=true;alerts.Checked=prefs.SystemMonitorAlerts;changing=false;stamp.Text="未保存："+e.Message;} };Controls.Add(alerts);
        var task=new BarcaButton{Text="打开任务管理器",Bounds=new(24,557,183,32)};task.Click+=async(_,_)=>await run("system_taskmanager");var security=new BarcaButton{Text="打开火绒",Bounds=new(221,557,140,32)};security.Click+=async(_,_)=>await run("system_securityclient");var path=new BarcaButton{Text="配置火绒路径…",Bounds=new(375,557,183,32)};path.Click+=(_,_)=>{using var picker=new OpenFileDialog{Filter="程序或快捷方式|*.exe;*.lnk"};if(picker.ShowDialog(this)!=DialogResult.OK)return;try{LocalApplications.Validate(new("0123456789abcdef0123456789abcdef","火绒",picker.FileName));save(p=>p.SecurityClientPath=picker.FileName);stamp.Text="路径已保存；此入口不读取或控制火绒防护状态。";}catch(Exception e){stamp.Text=e.Message;}};Controls.AddRange([task,security,path]);BarcaScrollTheme.Attach(processes);theme=new(this);monitor.Updated+=Render;Shown+=(_,_)=>Render();MinimumSize=MaximumSize=Size;
    }
    void Render(){if(IsDisposed||!Visible||monitor.Current is not{} s)return;cpu.Text=s.Cpu is{} c?$"{c:0.0}%":"采样中 / 暂不可读";memory.Text=s.TotalMemory is{} total&&s.AvailableMemory is{} free?$"{Bytes(total-free)} / {Bytes(total)}":"暂不可读取";network.Text=$"↓ {Bytes(s.Download)}/s   ↑ {Bytes(s.Upload)}/s";disk.Text=Bytes(s.DiskFree);processes.BeginUpdate();processes.Items.Clear();foreach(var p in s.Processes.OrderByDescending(p=>sortCpu?(p.Cpu??0):(double)(p.Memory??0)).ThenByDescending(p=>p.Memory??0).Take(12)){var item=new ListViewItem([p.Name,p.Id.ToString(),p.Cpu is{} load?$"{load:0.0}%":"—",Bytes(p.Memory)]);processes.Items.Add(item);}processes.EndUpdate();stamp.Text=$"更新于 {s.Time.LocalDateTime:HH:mm:ss} · 点击 CPU / 内存列排序 · 进程约4秒刷新，仅列可读项\n"+s.Note;}
    protected override void Dispose(bool disposing){if(disposing){monitor.Updated-=Render;theme.Dispose();}base.Dispose(disposing);}
}
sealed class MailClientForm:BarcaWindow
{
    readonly ModuleThemeBinding theme;
    public MailClientForm(Preferences prefs,Action<Action<Preferences>> save,Func<Task> open,bool preview=false)
    {
        Text="Leo · 邮箱客户端";ClientSize=new(650,340);Controls.Add(BarcaUi.Chrome(this,"使用你现有的邮箱客户端","Leo只提供快捷入口，不读取邮件、不保存邮箱凭据"));
        var note=new Label{Text="在 Foxmail、Thunderbird 或 Outlook 中管理 QQ、Gmail 和校园账户。\n配置后单击 Leo 的邮箱入口直接打开客户端。客户端通知仍由它自己负责。",Bounds=new(24,105,600,55),ForeColor=BarcaUi.Muted};var path=new TextBox{Text=!string.IsNullOrWhiteSpace(prefs.MailClientPath)?prefs.MailClientPath:preview?"":DesktopClients.Candidates(true).FirstOrDefault()??"",Bounds=new(24,171,465,28),BackColor=BarcaUi.Surface,ForeColor=BarcaUi.Text,PlaceholderText="选择已安装客户端的 EXE / LNK"};var choose=new BarcaButton{Text="选择…",Bounds=new(503,169,121,32)};choose.Click+=(_,_)=>{using var picker=new OpenFileDialog{Filter="程序或快捷方式|*.exe;*.lnk"};if(picker.ShowDialog(this)==DialogResult.OK)path.Text=picker.FileName;};var status=new Label{Bounds=new(24,215,600,32),ForeColor=BarcaUi.Muted};var launch=new BarcaButton{Text="保存并打开客户端",Bounds=new(24,254,210,34)};launch.Click+=async(_,_)=>{try{LocalApplications.Validate(new("0123456789abcdef0123456789abcdef","邮箱客户端",path.Text));save(p=>p.MailClientPath=path.Text);status.Text="客户端路径已保存。";await open();}catch(Exception e){status.Text=e.Message;}};
        void Web(string text,string url,int x){var button=new BarcaButton{Text=text,Bounds=new(x,302,145,28)};button.Click+=(_,_)=>{try{if(!preview)System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(url){UseShellExecute=true});}catch(Exception e){status.Text=e.Message;}};Controls.Add(button);}Web("QQ 邮箱网页版","https://mail.qq.com/",24);Web("Gmail 网页版","https://mail.google.com/",184);
        Controls.AddRange([note,path,choose,status,launch]);theme=new(this);MinimumSize=MaximumSize=Size;
    }
    protected override void Dispose(bool disposing){if(disposing)theme.Dispose();base.Dispose(disposing);}
}
